fn is_happy(s: Vec<char>) -> bool {
    // A sequence shorter than 3 can't be happy.
    if s.len() < 3 {
        return false;
    }

    // Check every contiguous window of length 3.
    for w in s.windows(3) {
        // If any two in the triple are equal, it's not happy.
        if w[0] == w[1] || w[0] == w[2] || w[1] == w[2] {
            return false;
        }
    }

    // All windows passed the distinctness test.
    true
}

