    #[test]
    fn test_happy_sequences() {
        assert!(!is_happy(vec!['a', 'a', 'a']));    // duplicates in every window
        assert!(!is_happy(vec!['a', 'b']));         // too short
        assert!(is_happy(vec!['a', 'b', 'c']));     // exactly 3 distinct
        assert!(is_happy(vec!['x', 'y', 'z', 'a'])); // all windows distinct
    }

    #[test]
    fn test_unhappy_sequences() {
        // the window at positions 1..=3 has duplicates
        assert!(!is_happy(vec!['x', 'y', 'x', 'z']));
        // overlapping windows: 0..=2 is distinct, but 1..=3 fails
        assert!(!is_happy(vec!['p', 'q', 'r', 'p']));
    }
